svg.script:
//
(function() {
  const svg = document.getElementById('p9-sarcopenia-svg');
  if (!svg) return;

  const classPreservado = 'active-preservado';
  const classSarcopenico = 'active-sarcopenico';

  // Elementos de Controle de Interface
  const btnPreservado = svg.querySelector('#p9-btn-preservado');
  const btnSarcopenico = svg.querySelector('#p9-btn-sarcopenico');
  const toggleSlide = svg.querySelector('#p9-toggle-slide');

  // Regiões Clicáveis
  const regPreservada = svg.querySelector('#p9-region-preservada');
  const regSarcopenica = svg.querySelector('#p9-region-sarcopenica');

  // Elementos de atualização textual do painel
  const textTitle = svg.querySelector('#p9-panel-title');
  const badgeRect = svg.querySelector('#p9-panel-badge-rect');
  const badgeText = svg.querySelector('#p9-panel-badge-text');

  const descL1 = svg.querySelector('#p9-desc-line-1');
  const descL2 = svg.querySelector('#p9-desc-line-2');
  const descL3 = svg.querySelector('#p9-desc-line-3');
  const descL4 = svg.querySelector('#p9-desc-line-4');

  const hotspots = svg.querySelectorAll('.p9-hotspot');

  // Base de dados clínicos e descritivos associados aos Hotspots
  const dataMap = {
    "hs-1": {
      title: "1. FIBRAS PRESERVADAS (TIPO II E I)",
      badge: "NORMAL",
      badgeColor: "var(--normal-green)",
      lines: [
        "Massa muscular esquelética com volume íntegro.",
        "As fibras musculares mantêm diâmetro ideal,",
        "capacidade máxima de contratilidade e reserva funcional",
        "para resposta imediata a sobrecargas motoras."
      ]
    },
    "hs-2": {
      title: "2. GORDURA SUBCUTÂNEA FISIOLÓGICA",
      badge: "NORMAL",
      badgeColor: "var(--normal-green)",
      lines: [
        "Camada adiposa subcutânea delgada e uniforme.",
        "Ausência de infiltração gordurosa nos septos",
        "intermusculares, mantendo o empacotamento das fáscias",
        "e a tração biomecânica sem interferência lipotóxica."
      ]
    },
    "hs-3": {
      title: "3. CORTICAL ÓSSEA INTEGRA & DENSE",
      badge: "NORMAL",
      badgeColor: "var(--normal-green)",
      lines: [
        "Cortical óssea espessa e sem sinais de porosidade.",
        "O estímulo mecânico e tensional de um músculo forte",
        "ativa as vias de mecanotransdução osteoblástica,",
        "garantindo densidade mineral óssea protetiva."
      ]
    },
    "hs-4": {
      title: "4. SARCOPENIA: ATROFIA & PERDA FIBRA",
      badge: "ALERTA CRÍTICO",
      badgeColor: "var(--alert-red)",
      lines: [
        "Atrofia severa e redução no número total de fibras.",
        "A perda acomete principalmente fibras de contração rápida",
        "(tipo II), levando à diminuição direta da velocidade de",
        "reação e força de preensão manual (critério clínico)."
      ]
    },
    "hs-5": {
      title: "5. MIOESTATOSE (INFILTRAÇÃO LIPÍDICA)",
      badge: "PATOLÓGICO",
      badgeColor: "var(--alert-red)",
      lines: [
        "Acúmulo ectópico de gordura e tecido fibroso.",
        "A gordura infiltra-se entre os feixes (mioesteatose),",
        "gerando inflamação subclínica, estresse oxidativo,",
        "e perda direta da qualidade de contração muscular."
      ]
    },
    "hs-6": {
      title: "6. OSTEOSARCOPENIA (OSSO POROSO)",
      badge: "ATENÇÃO",
      badgeColor: "var(--warn-orange)",
      lines: [
        "Cortical óssea afilada com microarquitetura porosa.",
        "A ausência de tração muscular e carga biomecânica",
        "desregula o remodelamento ósseo, acelerando a perda",
        "mineral e aumentando a fragilidade a fraturas."
      ]
    },
    "hs-7": {
      title: "7. METÁFORA: O IDOSO-PORCELANA",
      badge: "CONCEITO CHAVE",
      badgeColor: "var(--porcelain-cyan)",
      lines: [
        "A sarcopenia é a base da fragilidade senil.",
        "Como a porcelana, o idoso frágil parece íntegro mas,",
        "sem amortecimento muscular e sem reserva de torque,",
        "um leve impacto resulta em queda grave e fratura."
      ]
    }
  };

  const defaultTextPreservado = {
    title: "MÚSCULO PRESERVADO (VISÃO GERAL)",
    badge: "SAUDÁVEL",
    badgeColor: "var(--normal-green)",
    lines: [
      "Massa muscular e força conservadas em idoso ativo.",
      "Apresenta alta reserva funcional e capacidade de suportar",
      "estressores externos. Clique nos hotspots numerados (1, 2, 3)",
      "para analisar as estruturas específicas deste estado."
    ]
  };

  const defaultTextSarcopenico = {
    title: "MÚSCULO SARCOPÊNICO (VISÃO GERAL)",
    badge: "FRAGILIDADE",
    badgeColor: "var(--alert-red)",
    lines: [
      "Perda patológica de massa e força muscular associada à idade.",
      "O idoso perde a capacidade de amortecer impactos e manter",
      "o equilíbrio corporal. Clique nos hotspots (4, 5, 6, 7)",
      "para entender os mecanismos fisiopatológicos."
    ]
  };

  function updatePanelText(data) {
    textTitle.textContent = data.title;
    badgeRect.setAttribute('fill', data.badgeColor);
    badgeText.textContent = data.badge;

    descL1.textContent = data.lines[0] || "";
    descL2.textContent = data.lines[1] || "";
    descL3.textContent = data.lines[2] || "";
    descL4.textContent = data.lines[3] || "";
  }

  function switchState(state) {
    // Remove destaques de hotspots ao alternar a visualização
    hotspots.forEach(h => {
      h.querySelector('.hotspot-ring').classList.remove('hotspot-active');
    });

    if (state === 'preservado') {
      svg.className.baseVal = classPreservado;
      toggleSlide.setAttribute('x', '2');

      btnPreservado.querySelector('text').setAttribute('fill', 'var(--text-color)');
      btnSarcopenico.querySelector('text').setAttribute('fill', 'var(--text-muted)');

      regPreservada.className.baseVal = "region-group clickable state-active";
      regSarcopenica.className.baseVal = "region-group clickable state-inactive";

      updatePanelText(defaultTextPreservado);
    } else {
      svg.className.baseVal = classSarcopenico;
      toggleSlide.setAttribute('x', '112');

      btnPreservado.querySelector('text').setAttribute('fill', 'var(--text-muted)');
      btnSarcopenico.querySelector('text').setAttribute('fill', 'var(--text-color)');

      regPreservada.className.baseVal = "region-group clickable state-inactive";
      regSarcopenica.className.baseVal = "region-group clickable state-active";

      updatePanelText(defaultTextSarcopenico);
    }
  }

  // Handlers para botões de toggle
  btnPreservado.addEventListener('click', function(e) {
    e.stopPropagation();
    switchState('preservado');
  });

  btnSarcopenico.addEventListener('click', function(e) {
    e.stopPropagation();
    switchState('sarcopenico');
  });

  // Handlers de clique nas regiões (corte anatômico)
  regPreservada.addEventListener('click', function(e) {
    if (e.target.closest('.p9-hotspot')) return;
    switchState('preservado');
  });

  regSarcopenica.addEventListener('click', function(e) {
    if (e.target.closest('.p9-hotspot')) return;
    switchState('sarcopenico');
  });

  // Handlers de clique nos Hotspots
  hotspots.forEach(function(hotspot) {
    hotspot.addEventListener('click', function(e) {
      e.stopPropagation();

      // Limpa destaque de todos os hotspots
      hotspots.forEach(h => {
        h.querySelector('.hotspot-ring').classList.remove('hotspot-active');
      });

      // Adiciona destaque ao hotspot clicado
      hotspot.querySelector('.hotspot-ring').classList.add('hotspot-active');

      const hsId = hotspot.getAttribute('id');
      const data = dataMap[hsId];

      if (data) {
        // Se for hotspot sarcopênico (4, 5, 6, 7), garante que a cena sarcopênica está ativa
        if (hsId === 'hs-4' || hsId === 'hs-5' || hsId === 'hs-6' || hsId === 'hs-7') {
          if (svg.className.baseVal !== classSarcopenico) {
            svg.className.baseVal = classSarcopenico;
            toggleSlide.setAttribute('x', '112');
            btnPreservado.querySelector('text').setAttribute('fill', 'var(--text-muted)');
            btnSarcopenico.querySelector('text').setAttribute('fill', 'var(--text-color)');
            regPreservada.className.baseVal = "region-group clickable state-inactive";
            regSarcopenica.className.baseVal = "region-group clickable state-active";
          }
        } else {
          // Hotspot preservado (1, 2, 3)
          if (svg.className.baseVal !== classPreservado) {
            svg.className.baseVal = classPreservado;
            toggleSlide.setAttribute('x', '2');
            btnPreservado.querySelector('text').setAttribute('fill', 'var(--text-color)');
            btnSarcopenico.querySelector('text').setAttribute('fill', 'var(--text-muted)');
            regPreservada.className.baseVal = "region-group clickable state-active";
            regSarcopenica.className.baseVal = "region-group clickable state-inactive";
          }
        }
        // Atualiza painel com os dados do hotspot
        updatePanelText(data);
      }
    });
  });

  // Definir estado inicial ativo
  switchState('preservado');
})();
//
